/* reef demo — the chat.
 *
 * Two layers. The prepared questions are answered from data/qa.json, which was
 * generated by an agent that could read only the reef's artifacts; they cost nothing
 * and cannot fail. Free-typed questions go to the proxy, which answers the same way
 * against the whole reef. If the proxy is absent, over budget or unreachable, the
 * chat quietly loses its input box and keeps the prepared questions — the demo never
 * arrives at a broken state.
 */
import { state, t } from './site.js';

const API = window.REEF_API || '';          // set in the page; empty = prepared only
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c]));

let live = Boolean(API);
let history = [];
let el = {};

/* Render an answer: paragraphs, inline code, and citation chips that open the artifact. */
function renderAnswer(text, cites = []) {
  /* One bracket can hold several references, and some of them name source files
     rather than artifacts. Chip the ones that resolve; leave the rest as text. */
  const known = new Set([...(state.digest?.items || []).map(a => a.id), ...cites]);
  return esc(text)
    .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\[([^\]\n]+)\]/g, (m, inner) => {
      const parts = inner.split(/[,;]/).map(t => t.trim());
      if (!parts.some(t => known.has(t))) return m;
      return parts.map(t => known.has(t)
        ? `<button class="cite" data-artifact="${t}">${t}</button>`
        : `<span class="cite-plain">${t}</span>`).join(' ');
    })
    .split(/\n{2,}/).map(p => `<p>${p.replace(/\n/g, '<br>')}</p>`).join('');
}

function bubble(role, html, meta = '') {
  const div = document.createElement('div');
  div.className = `msg msg-${role}`;
  div.innerHTML = html + (meta ? `<p class="msg-meta">${meta}</p>` : '');
  el.log.append(div);
  div.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  return div;
}

function ask(text) {
  bubble('user', `<p>${esc(text)}</p>`);
  const canned = (state.qa?.items || []).find(it =>
    it.q.ko === text || it.q.en === text);

  if (canned) {
    const a = canned.a[state.lang] || canned.a.ko;
    bubble('bot', renderAnswer(a, canned.cites), `${t('chat.prepared')}`);
    return;
  }
  if (!live) { bubble('bot', `<p>${esc(t('chat.offline'))}</p>`); return; }
  askLive(text);
}

async function askLive(question) {
  const pending = bubble('bot', `<p class="thinking">···</p>`);
  el.form?.setAttribute('aria-busy', 'true');
  try {
    const r = await fetch(API, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ question, history: history.slice(-6) }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) {
      // Budget spent or misconfigured: stop offering the box rather than failing twice.
      if (['budget_spent', 'not_configured'].includes(data.error)) live = false;
      pending.innerHTML = `<p>${esc(t(live ? 'chat.error' : 'chat.spent'))}</p>`;
      syncInput();
      return;
    }
    history.push({ role: 'user', content: question },
                 { role: 'assistant', content: data.answer });
    pending.innerHTML = renderAnswer(data.answer, data.cites)
      + `<p class="msg-meta">${esc(data.model)} · ${t('chat.live')}</p>`;
  } catch {
    live = false;
    pending.innerHTML = `<p>${esc(t('chat.spent'))}</p>`;
    syncInput();
  } finally {
    el.form?.removeAttribute('aria-busy');
  }
}

function openArtifact(id) {
  const base = state.ev?.repos?.reef;
  const a = (state.digest?.items || []).find(x => x.id === id);
  el.panelTitle.textContent = id + (a ? ` — ${a.title}` : '');
  el.panelBody.innerHTML = a
    ? `<p class="tag">${a.type} · ${a.status} · verified ${a.verified}</p>`
      + '<ul>' + a.facts.map(f =>
          `<li>${esc(f.c)}${f.s ? ` <span class="src">${esc(f.s)}</span>` : ''}</li>`).join('') + '</ul>'
      + (a.unknowns?.length
          ? `<p class="tag">${t('chat.unknowns')}</p><ul>` +
            a.unknowns.map(u => `<li>${esc(u)}</li>`).join('') + '</ul>'
          : '')
    : `<p>${esc(id)}</p>`;
  el.panelLink.href = `${base}/blob/main/artifacts`;
  el.panel.hidden = false;
}

function syncInput() {
  if (el.form) el.form.hidden = !live;
  if (el.offline) el.offline.hidden = live;
}

function chips() {
  el.chips.innerHTML = '';
  (state.qa?.items || []).forEach(it => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.textContent = it.q[state.lang] || it.q.ko;
    b.addEventListener('click', () => ask(b.textContent));
    el.chips.append(b);
  });
}

export async function mountChat(root) {
  el = {
    log: root.querySelector('.chat-log'),
    chips: root.querySelector('.chat-chips'),
    form: root.querySelector('.chat-form'),
    input: root.querySelector('.chat-input'),
    offline: root.querySelector('.chat-offline'),
    panel: root.querySelector('.artifact-panel'),
    panelTitle: root.querySelector('.artifact-title'),
    panelBody: root.querySelector('.artifact-body'),
    panelLink: root.querySelector('.artifact-link'),
  };

  const base = document.body.dataset.base || '.';
  state.qa = await fetch(`${base}/data/qa.json`).then(r => r.json()).catch(() => ({ items: [] }));

  chips();
  syncInput();
  document.addEventListener('reef:lang', chips);

  el.form?.addEventListener('submit', e => {
    e.preventDefault();
    const v = el.input.value.trim();
    if (!v) return;
    el.input.value = '';
    ask(v);
  });

  root.addEventListener('click', e => {
    const c = e.target.closest('.cite');
    if (c) openArtifact(c.dataset.artifact);
    if (e.target.closest('.artifact-close')) el.panel.hidden = true;
  });
}
